UPDATE user_quota_overrides
SET free_trip_quota = #{freeTripQuota,jdbcType=INTEGER},
    ai_trip_free_quota = #{aiTripFreeQuota,jdbcType=INTEGER},
    ai_trip_pro_quota = #{aiTripProQuota,jdbcType=INTEGER},
    social_location_daily_limit = #{socialLocationDailyLimit,jdbcType=INTEGER},
    data_version = data_version + 1,
    updated_at = #{updatedAt,jdbcType=TIMESTAMP}
WHERE user_id = #{userId,javaType=java.util.UUID,jdbcType=OTHER}
  AND data_version = #{dataVersion,jdbcType=BIGINT}
